//! ECM definitions.
//!
//! All data derived from EcmDroid's `ecmdroid.db` lives in one file,
//! `data/ecmdroid.toml`, generated by `tools/extract_ecmdroid_db.py`. It can
//! be replaced without touching code. Which bikes an ECM ID shipped on is
//! XBTune's own data in `data/ecm_models.toml`. See `docs/PROVENANCE.md`.
//!
//! Phase 1 covers ECM identification and EEPROM page layouts. Variables,
//! tables, scalars and bit fields arrive in phase 2.

use std::collections::BTreeMap;
use std::fmt;

use serde::Deserialize;
use xbtune_proto::eeprom::{Layout, LayoutError};

/// The built-in ecmdroid.db-derived data.
pub const BUILTIN_ECMDROID: &str = include_str!("../../../data/ecmdroid.toml");
/// The built-in model hints.
pub const BUILTIN_MODELS: &str = include_str!("../../../data/ecm_models.toml");

/// ECM generation. Different firmware, EEPROM layout and variables.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Family {
    /// Tube-frame bikes. Out of scope.
    Ddfi1,
    /// 2003-2007 XB.
    Ddfi2,
    /// 2008+ XB (and 1125, which is out of scope).
    Ddfi3,
}

impl Family {
    /// True for the families XBTune supports.
    pub fn in_scope(self) -> bool {
        matches!(self, Self::Ddfi2 | Self::Ddfi3)
    }
}

impl fmt::Display for Family {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Ddfi1 => "DDFI",
            Self::Ddfi2 => "DDFI-2",
            Self::Ddfi3 => "DDFI-3",
        })
    }
}

/// One ECM firmware ID.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct EcmDef {
    /// Five-character ID, the start of the version string (e.g. `BUEIB`).
    pub id: String,
    /// Definition set the ID uses. Race and regional IDs share the street
    /// definitions, e.g. `B2RIB` uses `BUEIB`.
    pub definition: String,
    pub family: Family,
    /// EEPROM size without page 0.
    pub size: usize,
    /// EEPROM size with page 0.
    pub xsize: usize,
    /// Length of the full runtime-data reply frame.
    pub runtime_len: usize,
    pub remark: String,
    /// `[page number, page length]` pairs.
    pub pages: Vec<(u8, usize)>,
    /// Bikes this ID shipped on (from `ecm_models.toml`), if known.
    #[serde(skip)]
    pub bikes: Option<String>,
}

impl EcmDef {
    pub fn layout(&self) -> Result<Layout, LayoutError> {
        Layout::new(self.xsize, &self.pages)
    }

    /// True for factory/EBR race ECMs, which talk on address 0x55 at 19200 baud.
    pub fn is_race(&self) -> bool {
        self.remark.to_ascii_lowercase().contains("race")
    }
}

#[derive(Debug, thiserror::Error)]
pub enum DefsError {
    #[error("definition data: {0}")]
    Parse(#[from] toml::de::Error),
    #[error("ECM {id}: {source}")]
    Layout { id: String, source: LayoutError },
    #[error("ECM {id}: size {size} does not match layout ({actual})")]
    Size { id: String, size: usize, actual: usize },
}

#[derive(Deserialize)]
struct EcmFile {
    ecm: Vec<EcmDef>,
}

#[derive(Deserialize)]
struct ModelFile {
    model: Vec<Model>,
}

#[derive(Deserialize)]
struct Model {
    id: String,
    bikes: String,
}

/// All known ECMs.
#[derive(Debug, Clone)]
pub struct Catalog {
    ecms: BTreeMap<String, EcmDef>,
}

impl Catalog {
    /// Load the data files compiled into the binary.
    pub fn builtin() -> Result<Self, DefsError> {
        Self::from_toml(BUILTIN_ECMDROID, BUILTIN_MODELS)
    }

    pub fn from_toml(ecms: &str, models: &str) -> Result<Self, DefsError> {
        let file: EcmFile = toml::from_str(ecms)?;
        let models: ModelFile = toml::from_str(models)?;
        let mut map = BTreeMap::new();
        for mut def in file.ecm {
            let layout = def
                .layout()
                .map_err(|source| DefsError::Layout { id: def.id.clone(), source })?;
            if layout.size_without_page_zero() != def.size {
                return Err(DefsError::Size {
                    id: def.id.clone(),
                    size: def.size,
                    actual: layout.size_without_page_zero(),
                });
            }
            def.bikes = models.model.iter().find(|m| m.id == def.id).map(|m| m.bikes.clone());
            map.insert(def.id.clone(), def);
        }
        Ok(Self { ecms: map })
    }

    /// Find the definition for a version string such as `"BUEIB310 12-11-03"`.
    /// Only the first five characters identify the ECM.
    pub fn lookup(&self, version: &str) -> Option<&EcmDef> {
        let id: String = version.trim().chars().take(5).collect();
        self.ecms.get(&id)
    }

    pub fn iter(&self) -> impl Iterator<Item = &EcmDef> {
        self.ecms.values()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtin_loads_and_layouts_are_consistent() {
        let c = Catalog::builtin().unwrap();
        assert!(c.iter().count() >= 19);
        for def in c.iter() {
            let l = def.layout().unwrap();
            assert_eq!(l.xsize, def.xsize, "{}", def.id);
        }
    }

    #[test]
    fn bueib_is_ddfi2_with_page_zero() {
        let c = Catalog::builtin().unwrap();
        let d = c.lookup("BUEIB310 12-11-03").unwrap();
        assert_eq!(d.family, Family::Ddfi2);
        assert_eq!((d.size, d.xsize, d.runtime_len), (1206, 1210, 107));
        assert_eq!(d.layout().unwrap().page(0).unwrap().start, 1206);
        assert_eq!(d.bikes.as_deref(), Some("XB (2005-2007)"));
        assert!(!d.is_race());
    }

    #[test]
    fn race_ecm_shares_street_definition() {
        let c = Catalog::builtin().unwrap();
        let d = c.lookup("B2RIB").unwrap();
        assert_eq!(d.definition, "BUEIB");
        assert!(d.is_race());
    }

    #[test]
    fn ddfi3_ids_are_present() {
        let c = Catalog::builtin().unwrap();
        for id in ["BUEOD", "BUEWD", "BUEYD", "BUEZD", "BUE1D", "BUE2D", "BUE3D"] {
            assert_eq!(c.lookup(id).unwrap().family, Family::Ddfi3, "{id}");
        }
    }

    #[test]
    fn fixture_sizes_match() {
        let c = Catalog::builtin().unwrap();
        // EcmDroid's test EEPROM images are saved without page 0.
        assert_eq!(c.lookup("BUEIB").unwrap().size, 1206);
        assert_eq!(c.lookup("BUE2D").unwrap().size, 3756);
    }

    #[test]
    fn unknown_version() {
        assert!(Catalog::builtin().unwrap().lookup("XXXXX123").is_none());
    }
}
